namespace PhoenixmlDb.XQuery.FullText;

/// <summary>
/// Unicode 6.3 character classes for <see cref="WordTokenizer"/>, from the table generated by
/// tools/ucd/generate-word-break-data.py.
/// </summary>
internal static partial class WordBreakData
{
    internal const int Other = 0, ALetter = 1, HebrewLetter = 2, Numeric = 3, Katakana = 4,
        ExtendNumLet = 5, MidLetter = 6, MidNum = 7, MidNumLet = 8, SingleQuote = 9,
        DoubleQuote = 10, Extend = 11, RegionalIndicator = 12;   // Extend: Word_Break Extend or Format
    internal const int ComplexContext = 0x10, Han = 0x20, Hiragana = 0x40;

    internal static int Of(int codePoint)
        => codePoint < 0x10000 ? BmpTable.Values[codePoint] : Search(codePoint);

    // A class of its own: a static field initializer in this file would run before the one
    // holding RangeData in the generated file (the order of partial files is not defined).
    private static class BmpTable
    {
        internal static readonly byte[] Values = BuildBmp();
    }

    private static byte[] BuildBmp()
    {
        var table = new byte[0x10000];
        for (var i = 0; i < RangeData.Length; i += 3)
        {
            if (RangeData[i] > 0xFFFF)
                break;
            var last = Math.Min(RangeData[i + 1], 0xFFFF);
            for (var c = RangeData[i]; c <= last; c++)
                table[c] = (byte)RangeData[i + 2];
        }
        return table;
    }

    private static int Search(int codePoint)
    {
        int lo = 0, hi = RangeData.Length / 3 - 1;
        while (lo <= hi)
        {
            var mid = (lo + hi) >> 1;
            if (codePoint < RangeData[mid * 3]) hi = mid - 1;
            else if (codePoint > RangeData[mid * 3 + 1]) lo = mid + 1;
            else return RangeData[mid * 3 + 2];
        }
        return Other;
    }
}
